// FUXA's run and manual output bytes to the plant logic's messages: run
// first, then one switch message per bit of manual_out0 (bits 1-7, bit 0
// is the alarm's) and manual_out1. All bits are sent again after each
// change, so the outputs match the bytes when the running light goes off.
const m = context.get("m") || { manual_out0: 0, manual_out1: 0 };
const out = [];
if (msg.topic === "run") out.push({ topic: "run", payload: !!msg.payload });
else if (msg.topic in m) m[msg.topic] = Number(msg.payload) || 0;
else return null;
context.set("m", m);
for (let bit = 0; bit < 8; bit++) {
    if (bit > 0) out.push({ topic: "switch", payload: { name: "dio_out0", bit, value: !!(m.manual_out0 & (1 << bit)) } });
    out.push({ topic: "switch", payload: { name: "dio_out1", bit, value: !!(m.manual_out1 & (1 << bit)) } });
}
return [out];

// The example plant's logic, the same as PLANT_LOGIC in the CODESYS
// example: alarm when temperature 1 is over the limit, held until
// Ack while it is back under; the alarm sets output byte 0 bit 0. A light
// runs along output byte 1 (one bit every 500 ms tick) and the loop back
// is checked on input byte 1. Outputs: 1 canworks out, 2 page state,
// 3 trend points, 4 alarm notification.
const s = context.get("s") || {
    temp1: null, temp2: null, limit: 25.0, ack: false, run: true, alarm: false,
    in0: 0, in1: 0, out0: 0, out1: 0, user0: 0, user1: 0, pos: 0, lightOk: false,
    rtdOk: false, dioOk: false, bridge: "connecting", busOk: false
};
const out = [], trend = [];
let note = null;
const t = msg.topic, v = msg.payload;
if (t === "rtd.temp1" || t === "rtd.temp2") {
    const c = Number(v) / 10;
    if (t === "rtd.temp1") s.temp1 = c; else s.temp2 = c;
    trend.push({ topic: t === "rtd.temp1" ? "Temperature 1" : "Temperature 2", payload: c });
} else if (t === "dio.in0") s.in0 = Number(v) || 0;
else if (t === "dio.in1") s.in1 = Number(v) || 0;
else if (t === "rtd.status") s.rtdOk = !!v;
else if (t === "dio.status") s.dioOk = !!v;
else if (t === "bridge.state") s.bridge = String(v);
else if (t === "bridge.bus_ok") s.busOk = !!v;
else if (t === "limit" && Number.isFinite(Number(v))) s.limit = Number(v);
else if (t === "ack") s.ack = true;
else if (t === "run") s.run = !!v;
else if (t === "switch" && v && typeof v === "object") {
    const m = 1 << v.bit;
    if (v.name === "dio_out0" && v.bit > 0) s.user0 = v.value ? s.user0 | m : s.user0 & ~m;
    if (v.name === "dio_out1" && !s.run) s.user1 = v.value ? s.user1 | m : s.user1 & ~m;
}
// The alarm.
const was = s.alarm;
if (s.temp1 !== null && s.temp1 > s.limit) s.alarm = true;
else if (s.ack) s.alarm = false;
s.ack = false;
if (s.alarm && !was) note = { payload: "Temperature 1 is over " + s.limit.toFixed(1) + " °C", topic: "Alarm" };
// The running light: a step every tick while running.
if (t === "tick" && s.run) {
    s.lightOk = s.in1 === s.out1;
    s.pos = (s.pos + 1) % 8;
}
if (!s.run) s.lightOk = false;
const out0 = (s.alarm ? 1 : 0) | (s.user0 & 0xfe);
const out1 = s.run ? 1 << s.pos : s.user1;
if (out0 !== s.out0 || t === "start") { s.out0 = out0; out.push({ topic: "dio.out0", payload: out0 }); }
if (out1 !== s.out1 || t === "start") { s.out1 = out1; out.push({ topic: "dio.out1", payload: out1 }); }
context.set("s", s);
const state = { topic: "state", payload: {
    temp1: s.temp1, temp2: s.temp2, limit: s.limit, alarm: s.alarm, run: s.run, lightOk: s.lightOk,
    rtdOk: s.rtdOk, dioOk: s.dioOk, bridge: s.bridge, busOk: s.busOk,
    dio_in0: s.in0, dio_in1: s.in1, dio_out0: s.out0, dio_out1: s.out1
} };
const last = context.get("last");
const text = JSON.stringify(state.payload);
context.set("last", text);
return [out, text === last ? null : state, trend, note];

// The plant state to the tags of the FUXA Server device (tag id = name).
// A value is written when the tag holds another one, which also refills
// the tags after FUXA reloads its project. limit, run, ack and the manual
// bytes belong to the operator and are not written here.
const fuxa = global.get("fuxa");
const s = msg.payload;
const values = {
    temp1: s.temp1, temp2: s.temp2, alarm: s.alarm, light_ok: s.lightOk,
    rtd_ok: s.rtdOk, dio_ok: s.dioOk, bus_ok: s.busOk, bridge_state: s.bridge,
    canworks_ok: s.bridge === "running" && s.busOk,
    dio_in0: s.dio_in0, dio_in1: s.dio_in1, dio_out0: s.dio_out0, dio_out1: s.dio_out1
};
for (const [id, v] of Object.entries(values)) {
    if (v !== null && v !== undefined && fuxa.getTag(id) !== v) fuxa.setTag(id, v);
}
return null;
